// Statically recompiled SPU programs (generated by recomp/spu_recompile.py into
// game/generated/spu/). Each is a fixed binary from the EBOOT, identified by its
// guest address and size and checked against a hash of its bytes before first use.
#pragma once

#include "spu/spu.h"

namespace spu {

// Runs from s.pc. Returns 1 + StopReason when the program stops, or 0 when it
// reaches code it was not compiled for (s.pc says where; continue in the interpreter).
using CompiledFn = u32 (*)(SPU& s, u32* code);

struct CompiledProgram {
	const char* name;
	u32 ea, size;      // where the binary lives in guest memory
	u32 ls_base;       // where it was compiled to run in local store
	u64 hash;          // FNV-1a 64 of the binary
	CompiledFn fn;
};

struct CompiledRegistrar {
	explicit CompiledRegistrar(const CompiledProgram& p);
};

// The compiled program for the binary at [ea, ea+size) loaded at ls_base, if any
// (and if its bytes still match). Disabled with SPU_INTERPRET=1.
const CompiledProgram* find_compiled(u32 ea, u32 size, u32 ls_base);

// Run a binary, compiled if possible, falling back to the interpreter.
// SPU_VERIFY=1 also runs the interpreter on a copy and reports any difference.
StopReason run_program(SPU& s, u32 ea, u32 size, u32 ls_base, u32* code, u64 max_instructions);

} // namespace spu
